    static async getData(path) {
        const url = path;
        try {
            const response = await fetch(url);
            if (!response.ok) {
                throw new Error(`Response status: ${response.status}`);
            }
            const json = await response.json();
            //console.log(json);
            return json;
        }
        catch (error) {
            if (console && error instanceof Error)
                console.error(error.message);
            else
                throw error;
        }
    }
