        let hd = this.getFontHeightandDescent(modifierFont, frc);
        let modifierFontHeight = hd[0];
        let modifierFontDescent = hd[1];
        let bufferHorizontal = modifierFontHeight / 2;
        let bufferXL = bufferHorizontal;
        let bufferXR = bufferHorizontal;
        let bufferY = 2;
        let bufferText = 2;
        let x = 0;
        let y = 0; //best y
        let newsdi;
        let alpha = -1;
        let textColor = Color_1.Color.BLACK;
        let textBackgroundColor;
        let tiArray = new Array();
        if (attributes.has(MilStdAttributes_1.MilStdAttributes.Alpha)) {
            alpha = parseFloat(attributes.get(MilStdAttributes_1.MilStdAttributes.Alpha)) / 255;
        }
        let labelBounds;
        let labelWidth = 0;
        let labelHeight = 0;
        let bounds = (sdi.getSymbolBounds().clone());
