                    labelWidth = Math.round(ti.getTextBounds().getWidth());
                    //points
                    x = (bounds.getMinX() + (bounds.getWidth() * 0.5));
                    x = x - (labelWidth * 0.5);
                    //y = bounds.y + (bounds.getHeight * 0.5);
