    /**
     * Customer requested routine for setting the stroke dash pattern
     * Scales dash length with line width and DPI
     * @param width
     * @param style
     * @param cap
     * @param join
     * @return
     */
    static getLineStroke(width, style, cap, join) {
        // Some segments are of length 0.1 because the Java2D renderer adds line caps of
        // width/2 size to both ends of the segment when "round" is one of BasicStroke.CAP_ROUND
        // or BasicStroke.CAP_SQUARE. This value is small enough not to affect the
        // stipple bit pattern calculation for the 3d map and still look good on the
        // 2d map.
        // NOTE: The dash arrays below do not supportBasisStroke.CAP_BUTT line capping,
        // although it would be relatively simple to change them such that they would.
        let stroke;
        try {
            let dashLength = 2 * width;
            let dotLength = 1;
            let dotSpace = 2 * width;
            switch (style) {
                case 0: { //GraphicProperties.LINE_TYPE_SOLID:
                    stroke = new BasicStroke_1.BasicStroke(width, cap, join);
                    break;
                }
                case 1: { //GraphicProperties.LINE_TYPE_DASHED:
                    let dash = [dashLength, dashLength];
                    stroke = new BasicStroke_1.BasicStroke(width, cap, join, 4, dash, 0);
                    break;
                }
                case 2: { //GraphicProperties.LINE_TYPE_DOTTED:
                    let dot = [dotLength, dotSpace];
                    stroke = new BasicStroke_1.BasicStroke(width, cap, join, 4, dot, 0);
                    break;
                }
                case 3: { //GraphicProperties.LINE_TYPE_DASHDOT:
                    let dashdot = [2 * dashLength, dotSpace, dotLength, dotSpace];
                    stroke = new BasicStroke_1.BasicStroke(width, cap, join, 4, dashdot, 0);
                    break;
                }
                case 4: { //GraphicProperties.LINE_TYPE_DASHDOTDOT:
                    let dashdotdot = [dashLength, dotSpace, dotLength, dotSpace, dotLength, dotSpace];
                    stroke = new BasicStroke_1.BasicStroke(width, cap, join, 4, dashdotdot, 0);
                    break;
                }
                default: {
                    stroke = new BasicStroke_1.BasicStroke(width, cap, join);
                    break;
                }
            }
        }
        catch (exc) {
            if (exc instanceof Error) {
                ErrorLogger_1.ErrorLogger.LogException(clsUtility._className, "getLineStroke", new RendererException_1.RendererException("Failed inside getLineStroke", exc));
            }
            else {
                throw exc;
            }
        }
        return stroke;
    }
