            lastSegmentPt1.y = pixels[2 * numPOINT2s - 5];
            lastSegmentPt2.x = pixels[2 * numPOINT2s - 4];
            lastSegmentPt2.y = pixels[2 * numPOINT2s - 3];
            channelWidthPOINT2.x = pixels[2 * numPOINT2s - 2];
            channelWidthPOINT2.y = pixels[2 * numPOINT2s - 1];
            let m = new ref_1.ref();
            let m1 = 0;
            //m1.value=new double[1];
            let distance = 0;
            let ptIntersect = new POINT2_1.POINT2(0, 0);
            //boolean bolVertical = TrueSlope(lastSegmentPt1, lastSegmentPt2, ref m);
            let bolVertical = lineutility_1.lineutility.CalcTrueSlopeDouble2(lastSegmentPt1, lastSegmentPt2, m);
