    /**
     * Client utility to calculate the channel points for channel types.
     * This code was ported from CJMTK.
     * @param arrLocation the client points
     * @return the channel point
     */
    static ComputeLastPoint(arrLocation) {
        let locD = new POINT2_1.POINT2(0, 0);
        try {
            let locA = arrLocation[1];
            //Get the first point (b) in pixels.
            //var locB:Point=new Point(arrLocation[0].x,arrLocation[0].y);
            let locB = arrLocation[0];
            //Compute the distance in pixels from (a) to (b).
            let dblDx = locB.x - locA.x;
            let dblDy = locB.y - locA.y;
            //Compute the dblAngle in radians from (a) to (b).
            let dblTheta = Math.atan2(-dblDy, dblDx);
            //Compute a reasonable intermediate point along the line from (a) to (b).
            let locC = new POINT2_1.POINT2(0, 0);
            locC.x = Math.trunc(locA.x + 0.85 * dblDx);
            locC.y = Math.trunc(locA.y + 0.85 * dblDy);
            //Put the last point on the left side of the line from (a) to (b).
            let dblAngle = dblTheta + Math.PI / 2.0;
            if (dblAngle > Math.PI) {
                dblAngle = dblAngle - 2.0 * Math.PI;
            }
            if (dblAngle < -Math.PI) {
                dblAngle = dblAngle + 2.0 * Math.PI;
            }
            //Set the magnitude of the dblWidth in pixels.  Make sure it is at least 15 pixels.
            let dblWidth = 30; //was 15
            //Compute the last point in pixels.
            locD.x = (locC.x + dblWidth * Math.cos(dblAngle));
            locD.y = (locC.y - dblWidth * Math.sin(dblAngle));
        }
        catch (exc) {
            if (exc instanceof Error) {
                //clsUtility.WriteFile("Error in clsUtility.ComputeLatPoint");
                ErrorLogger_1.ErrorLogger.LogException(clsUtility._className, "ComputeLastPoint", new RendererException_1.RendererException("Failed inside ComputeLastPoint", exc));
            }
            else {
                throw exc;
            }
        }
        return locD;
    }
    /**
     * Called by clsChannelUtility. The segments are used for managing double-backed segments
     * for channel types. If the new point is double-backed then the segment at that index will be false.
     *
     * @param pixels the client points as 2-tuples x,y in pixels
     * @param segments OUT - the segments
     * @param factor a steepness factor for calculating whether the segment is double-backed
     */
    static GetSegments(pixels, segments, factor) {
        try {
            let j = 0;
            let m1 = new ref_1.ref();
            let m2 = new ref_1.ref();
            let numPoints = 0;
            let bolVertical1 = false;
            let bolVertical2 = false;
            let pt0F = new POINT2_1.POINT2(0, 0);
            let pt1F = new POINT2_1.POINT2(0, 0);
            let pt2F = new POINT2_1.POINT2(0, 0);
            segments[0] = true;
            numPoints = pixels.length / 2;
            for (j = 0; j < numPoints - 2; j++) {
                pt0F.x = pixels[2 * j];
                pt0F.y = pixels[2 * j + 1];
                pt1F.x = pixels[2 * j + 2];
                pt1F.y = pixels[2 * j + 3];
                pt2F.x = pixels[2 * j + 4];
                pt2F.y = pixels[2 * j + 5];
                bolVertical1 = lineutility_1.lineutility.CalcTrueSlopeDoubleForRoutes(pt0F, pt1F, m1);
                bolVertical2 = lineutility_1.lineutility.CalcTrueSlopeDoubleForRoutes(pt1F, pt2F, m2);
                segments[j + 1] = true;
                if (bolVertical1 === true && bolVertical2 === true) {
                    if (Math.abs(Math.atan(m1.value[0]) - Math.atan(m2.value[0])) < 1 / factor && clsUtility.InXOrder(pt0F, pt1F, pt2F) === false) //was 0.1
                     {
                        segments[j + 1] = false;
                    }
                }
                if ((bolVertical1 === false || Math.abs(m1.value[0]) > factor) && (bolVertical2 === false || Math.abs(m2.value[0]) > factor) && clsUtility.InYOrder(pt0F, pt1F, pt2F) === false) //was 10
                 {
                    segments[j + 1] = false;
                }
            } //end for
            //int n=segments.length;
        }
        catch (exc) {
            if (exc instanceof Error) {
                //console.log(e.message);
                //clsUtility.WriteFile("Error in clsUtility.GetSegments");
                ErrorLogger_1.ErrorLogger.LogException(clsUtility._className, "GetSegments", new RendererException_1.RendererException("Failed inside GetSegments", exc));
            }
            else {
                throw exc;
            }
        }
    }
    static GetLCPartitions(pixels, LCChannelWith, partitions, singleLinePartitions) {
        try {
            let numPoints = pixels.length / 2;
            let pt0F = new POINT2_1.POINT2(0, 0);
            let pt1F = new POINT2_1.POINT2(0, 0);
            let pt2F = new POINT2_1.POINT2(0, 0);
            let nextP = new P1_1.P1();
            nextP.start = 0;
            //used for debugging
            let angles = new Array(numPoints - 1);
            for (let i = 0; i < numPoints - 2; i++) {
                pt0F.x = pixels[2 * i];
                pt0F.y = pixels[2 * i + 1];
                pt1F.x = pixels[2 * i + 2];
                pt1F.y = pixels[2 * i + 3];
                pt2F.x = pixels[2 * i + 4];
                pt2F.y = pixels[2 * i + 5];
                let angle1 = Math.atan2(pt1F.y - pt0F.y, pt1F.x - pt0F.x);
                let angle2 = Math.atan2(pt1F.y - pt2F.y, pt1F.x - pt2F.x);
                let angle = angle1 - angle2; // * 180/Math.PI;
                let degrees = angle * 180 / Math.PI;
                if (angle < 0) {
                    degrees = 360 + degrees;
                }
                if (degrees > 270) {
                    let angleTooSmall = false;
                    if (lineutility_1.lineutility.CalcDistanceDouble(pt0F, pt1F) < lineutility_1.lineutility.CalcDistanceDouble(pt1F, pt2F)) {
                        let newPt = lineutility_1.lineutility.ExtendAlongLineDouble2(pt1F, pt2F, lineutility_1.lineutility.CalcDistanceDouble(pt1F, pt0F));
                        if (lineutility_1.lineutility.CalcDistanceDouble(pt0F, newPt) < LCChannelWith) {
                            angleTooSmall = true;
                        }
                    }
                    else {
                        let newPt = lineutility_1.lineutility.ExtendAlongLineDouble2(pt1F, pt0F, lineutility_1.lineutility.CalcDistanceDouble(pt1F, pt2F));
                        if (lineutility_1.lineutility.CalcDistanceDouble(pt2F, newPt) < LCChannelWith) {
                            angleTooSmall = true;
                        }
                    }
                    if (angleTooSmall) {
                        // Angle is too small to fit channel, make it a single line partition
                        nextP.end_Renamed = i - 1;
                        partitions.push(nextP);
                        nextP = new P1_1.P1();
                        nextP.start = i;
                        nextP.end_Renamed = i + 2;
                        singleLinePartitions.push(nextP);
                        i++;
                        nextP = new P1_1.P1();
                        nextP.start = i + 1;
                    }
                }
                else {
                    if (degrees < 90) {
                        // new Partition
                        nextP.end_Renamed = i;
                        partitions.push(nextP);
                        nextP = new P1_1.P1();
                        nextP.start = i + 1;
                    }
                }
                angles[i] = degrees;
            } //end for
            nextP.end_Renamed = numPoints - 2;
            partitions.push(nextP);
        }
        catch (exc) {
            if (exc instanceof Error) {
                ErrorLogger_1.ErrorLogger.LogException(clsUtility._className, "GetLCPartitions", new RendererException_1.RendererException("Failed inside GetLCPartitions", exc));
            }
            else {
                throw exc;
            }
        }
    }
