    /**
     * USAS requires a left-right orientation for ENY, which negates the upper-lower
     * orientation we used for Mil-Std-2525 ENY compliance. Therefore we must reverse
     * the client points for two of the quadrants
     * @param tg tactical graphic
     */
    static ReverseUSASLCPointsByQuadrant(tg) {
        try {
            if (tg.Pixels.length < 2) {
                return;
            }
            let quadrant = lineutility_1.lineutility.GetQuadrantDouble(tg.Pixels[0], tg.Pixels[1]);
            switch (tg.get_LineType()) {
                case TacticalLines_1.TacticalLines.LC: {
                    if (tg.isHostile()) {
                        switch (quadrant) {
                            case 2:
                            case 3: {
                                break;
                            }
                            case 1: //reverse the points for these two quadrants
                            case 4: {
                                let n = tg.Pixels.length;
                                let pts2 = [...tg.Pixels];
                                //for(int j=0;j<tg.Pixels.length;j++)
                                for (let j = 0; j < n; j++) {
                                    tg.Pixels[j] = pts2[n - j - 1];
                                }
                                break;
                            }
                            default:
                        } //end switch quadrant
                    } //end if
                    else {
                        switch (quadrant) {
                            case 1:
                            case 4: {
                                break;
                            }
                            case 2: //reverse the points for these two quadrants
                            case 3: {
                                let n = tg.Pixels.length;
                                let pts2 = [...tg.Pixels];
                                //for(int j=0;j<tg.Pixels.length;j++)
                                for (let j = 0; j < n; j++) {
                                    tg.Pixels[j] = pts2[n - j - 1];
                                }
                                break;
                            }
                            default:
                        } //end switch quadrant
                    }
                    break;
                }
                //end else
                default: {
                    break;
                }
            } //end switch linetype
        }
        catch (exc) {
            if (exc instanceof Error) {
                //WriteFile("Error in clsUtility.SetLCColor");
                ErrorLogger_1.ErrorLogger.LogException(clsUtility._className, "ReverseUSASLCPointsByQuadrant", new RendererException_1.RendererException("Failed inside ReverseUSASLCPointsByQuadrant", exc));
            }
            else {
                throw exc;
            }
        }
    } //end ReverseUSASLCPointsByQuadrant
    /**
     * use str if tg is null
     * @param symbolId Mil=Standard-2525 symbol id
     * @return line type
     */
    static GetLinetypeFromString(symbolId) {
        try {
            if (symbolId.length < 16) {
                return -1;
            }
            let symbolSet = SymbolID_1.SymbolID.getSymbolSet(symbolId);
            let entityCode = SymbolID_1.SymbolID.getEntityCode(symbolId);
            let version = SymbolID_1.SymbolID.getVersion(symbolId);
            if (symbolSet === 25) {
                return clsRenderer_1.clsRenderer.getCMLineType(version, entityCode);
            }
            else {
                if (symbolSet === 45 || symbolSet === 46) {
                    return clsMETOC_1.clsMETOC.getWeatherLinetype(version, entityCode);
                }
            }
        }
        catch (exc) {
            if (exc instanceof Error) {
                ErrorLogger_1.ErrorLogger.LogException(clsUtility._className, "GetLinetypeFromString", new RendererException_1.RendererException("Failed inside GetLinetypeFromString", exc));
            }
            else {
                throw exc;
            }
        }
        return -1;
    }
    /**
     * An auto-shape is a symbol with a fixed number of anchor points
     *
     * @param tg tactical graphic
     * @return true if auto-shape
     */
    static isAutoshape(tg) {
        try {
            switch (tg.get_LineType()) {
                case TacticalLines_1.TacticalLines.BBS_RECTANGLE:
                case TacticalLines_1.TacticalLines.BS_RECTANGLE:
                case TacticalLines_1.TacticalLines.BS_ELLIPSE:
                case TacticalLines_1.TacticalLines.PBS_CIRCLE:
                case TacticalLines_1.TacticalLines.BS_CROSS:
                case TacticalLines_1.TacticalLines.BS_BBOX:
                case TacticalLines_1.TacticalLines.BBS_POINT:
                    return true;
            }
            let msInfo = MSLookup_1.MSLookup.getInstance().getMSLInfo(tg.get_SymbolId());
            if (msInfo == null || clsUtility.IsChange1Area(tg.get_LineType())) {
                return false;
            }
            switch (tg.get_LineType()) {
                case TacticalLines_1.TacticalLines.DIRATKAIR:
                case TacticalLines_1.TacticalLines.DIRATKGND:
                case TacticalLines_1.TacticalLines.DIRATKSPT:
                case TacticalLines_1.TacticalLines.INFILTRATION: {
                    // Direction of attack symbols only have two points but can handle more
                    return false;
                }
                default: {
                    break;
                }
            }
            switch (msInfo.getDrawRule()) {
                case DrawRules_1.DrawRules.LINE26: // Two ways to draw but fixed points
                case DrawRules_1.DrawRules.LINE27: // Two ways to draw but fixed points
                case DrawRules_1.DrawRules.AREA26: // Need same number of points in first half and second half to make two shapes
                case DrawRules_1.DrawRules.CORRIDOR1: { // Each point represents an Air Control Point or Communications Checkpoint
                    return true;
                }
                default: {
                    return msInfo.getMaxPointCount() === msInfo.getMinPointCount();
                }
            }
        }
        catch (exc) {
            if (exc instanceof Error) {
                ErrorLogger_1.ErrorLogger.LogException(clsUtility._className, "isAutoshape", new RendererException_1.RendererException("Failed inside isAutoshape", exc));
            }
            else {
                throw exc;
            }
        }
        return false;
    }
